window.NARRATION = [{"dur": 21.74, "cues": [{"t": 0.1, "e": 5.1, "text": "BOX AI Agentは、検索だけのAIではありません。"}, {"t": 5.35, "e": 21.04, "text": "Box上に保存されている物件資料や価格表、PJコード、サービス枠管理表、稟議関連資料などをもとに、必要な情報の確認や要約、抽出、複数資料の整理まで、チャット形式で行うことができます。"}]}, {"dur": 33.197, "cues": [{"t": 0.1, "e": 13.893, "text": "Box AIは、通常のチャットAIのように単体で回答するだけではなく、Box上の資料を参照しながら、複数のAIモデルやエージェント機能を組み合わせて処理します。"}, {"t": 14.143, "e": 24.143, "text": "機密情報の取り扱いや画像の読み込みにも複数のエージェントを活用しているため、精度の高い結果が得られやすい仕組みです。"}, {"t": 24.393, "e": 32.497, "text": "Box上に資料が整理されているほど、検索や要約、一覧化、下書き作成などに活用しやすくなります。"}]}, {"dur": 36.033, "cues": [{"t": 0.1, "e": 5.617, "text": "Box内に点在する複数の資料を、横断して参照することもできます。"}, {"t": 5.867, "e": 20.35, "text": "物件資料や価格表、PJコード一覧、サービス枠管理表に加えて、広告宣伝費、工程表、収支表、契約書など、フォルダをまたいで散らばっている資料をAIがまわりながら参照します。"}, {"t": 20.6, "e": 28.186, "text": "そのうえで、物件ごとの基本情報や価格、PJコード、確認事項をひとつにまとめて出力します。"}, {"t": 28.436, "e": 35.333, "text": "資料を一つずつ開いて確認する手間を減らし、情報整理の初動を早めることができます。"}]}, {"dur": 33.714, "cues": [{"t": 0.1, "e": 8.893, "text": "Box内の資料をAIで活用しやすくするためには、共通のキーとなる情報を意識して保存することが重要です。"}, {"t": 9.143, "e": 21.04, "text": "当社では物件ごとにPJコードが紐づいているため、資料名やフォルダ名、ファイル内の記載には、できるだけPJコードを含めるようにしてください。"}, {"t": 21.29, "e": 33.014, "text": "これにより、異なる資料をまたいだ参照や紐づけがしやすくなり、後から検索・抽出・集約する際にも、必要な情報を正確に引き出しやすくなります。"}]}, {"dur": 39.826, "cues": [{"t": 0.1, "e": 7.686, "text": "具体的な使い方としては、対象となるファイルやフォルダを選び、その内容について質問します。"}, {"t": 7.936, "e": 26.902, "text": "このフォルダ内の資料を要約してください、物件名とPJコードを一覧化してください、価格情報を整理してください、サービス枠管理表からこの物件の残額を確認してください、稟議・決裁資料の下書きを作成してください、といった形です。"}, {"t": 27.152, "e": 32.152, "text": "ただし、今できるのはここまでで、出力形式もまだ限定的です。"}, {"t": 32.402, "e": 39.126, "text": "実際のファイルを編集するなど、タスクそのものを完了させることはまだできません。"}]}, {"dur": 30.248, "cues": [{"t": 0.1, "e": 2.169, "text": "実際にやってみた例です。"}, {"t": 2.419, "e": 8.109, "text": "物件リストにPJコードと価格を付与し、顧客情報を紐づけてみました。"}, {"t": 8.359, "e": 16.979, "text": "物件概要が収納されているフォルダを指定して、中のファイルの概要を見やすくHTMLにまとめてみました。"}, {"t": 17.229, "e": 24.126, "text": "さらに、ラクモのワークフローに合わせて、決裁書の内容の下書きを作成してみました。"}, {"t": 24.376, "e": 29.548, "text": "点在する情報を、確認しやすい形に整理する用途で活用できます。"}]}, {"dur": 32.929, "cues": [{"t": 0.1, "e": 3.893, "text": "AIは、それぞれのBox権限の中で動きます。"}, {"t": 4.143, "e": 11.212, "text": "そのため、自分の権限が及ぶ範囲に情報を蓄積していくイメージで資料を集めてください。"}, {"t": 11.462, "e": 21.807, "text": "その際は、AIが突合させやすいように、PJコードなど一定のキーを中心に整理しながら格納すると、後から探しやすくなります。"}, {"t": 22.057, "e": 32.229, "text": "なお、GoogleワークスペースとBoxの連携は許可されているため、Gmailの本文をBoxに蓄積する機能もあります。"}]}, {"dur": 30.171, "cues": [{"t": 0.1, "e": 2.686, "text": "プロンプトの書き方も重要です。"}, {"t": 2.936, "e": 9.488, "text": "対象となる資料、確認したい項目、出力の形を、そのまま具体的に書いてください。"}, {"t": 9.738, "e": 21.462, "text": "例えば、このフォルダの内容を突合して、決裁資料用の売価、税額、サービス枠残額、粗利などの数字をまとめて表示してください、といった形です。"}, {"t": 21.712, "e": 29.471, "text": "見てほしい資料と、欲しい項目、出したい形を丁寧に書くほど、実務で使いやすい結果になります。"}]}, {"dur": 28.007, "cues": [{"t": 0.1, "e": 1.134, "text": "注意点です。"}, {"t": 1.384, "e": 6.212, "text": "このAIは、背景などのコンテキストをまだ蓄積できません。"}, {"t": 6.462, "e": 11.634, "text": "そのため、毎回のプロンプトでしっかり説明する必要があります。"}, {"t": 11.884, "e": 22.229, "text": "特に初回のプロンプトが重要になりますので、事前にチャットGPTなどを活用してプロンプトを作成してから使ってみてください。"}, {"t": 22.479, "e": 27.307, "text": "うまく出力できたプロンプトは、ぜひ共有していきましょう。"}]}, {"dur": 28.869, "cues": [{"t": 0.1, "e": 4.238, "text": "また、BOX AIには1日の利用制限があります。"}, {"t": 4.488, "e": 8.281, "text": "制限を超えると、動作するモデルが下がります。"}, {"t": 8.531, "e": 14.91, "text": "この赤い表示が出たら、Box Agent Liteで動作している状態です。"}, {"t": 15.16, "e": 23.609, "text": "モデルが下がった後は、横断整理や複雑な下書きなどの重い作業は避けて、作業は軽めにしておきましょう。"}, {"t": 23.859, "e": 28.169, "text": "今後、プロンプトを含めて改善されていくと思います。"}]}, {"dur": 18.024, "cues": [{"t": 0.1, "e": 6.134, "text": "まずは身近なフォルダや管理表から、無理のない範囲で試してみてください。"}, {"t": 6.384, "e": 12.247, "text": "Box上に資料を整理・蓄積していくことが、今後の活用につながります。"}, {"t": 12.497, "e": 17.324, "text": "活用事例やうまくいったプロンプトは、ぜひご共有ください。"}]}];
